$passed=0;
function check(bool $value,string $name): void { global $passed; if(!$value)throw new RuntimeException('FAIL: '.$name);$passed++;echo "PASS: $name\n"; }
function rejects(callable $fn,string $name): void {try{$fn();}catch(InvalidArgumentException|RuntimeException $ex){check(true,$name);return;}check(false,$name);}
$admin=one("SELECT * FROM users WHERE role='admin'");$_SESSION['user_id']=$admin['id'];
query('INSERT INTO users (name,email,password_hash,role,active,created_at) VALUES (?,?,?,?,1,?)',['ผู้เขียนทดสอบ','author@example.test',password_hash('A7!test9Kx2Q',PASSWORD_DEFAULT),'author',now()]);
$author=one("SELECT * FROM users WHERE role='author'");$category=(int)query('SELECT id FROM categories LIMIT 1')->fetchColumn();
query('INSERT INTO media (name,path,mime,size,alt,uploaded_by,created_at) VALUES (?,?,?,?,?,?,?)',['image.webp','test.webp','image/webp',100,'ภาพทดสอบ',$admin['id'],now()]);$cover=(int)db()->lastInsertId();
$input=['type'=>'post','title'=>'ข่าวทดสอบภาษาไทย','slug'=>'test-news','excerpt'=>'ตัวอย่าง','body'=>'ข้อความข่าว','status'=>'draft','category_id'=>$category,'cover_id'=>$cover];
$id=save_content($input,$author,null);$row=one('SELECT * FROM contents WHERE id=?',[$id]);check((int)$row['author_id']===(int)$author['id'],'draft ownership');
check(visible_content('test-news','post')===null,'draft is not public');
