$bad=array_merge($publish,['cover_id'=>'']);rejects(fn()=>save_content($bad,$admin,$row),'published news requires cover');
save_content($publish,$admin,$row);check(visible_content('test-news','post')!==null,'published content visible');
rejects(fn()=>save_content($publish,$admin,$row),'stale version rejected');
$row=one('SELECT * FROM contents WHERE id=?',[$id]);
save_content(array_merge($input,['slug'=>'renamed-news','status'=>'published','version'=>$row['version']]),$admin,$row);
check(one('SELECT content_id FROM slug_redirects WHERE old_slug=?',['test-news'])!==null,'old URL redirect recorded');
$future=array_merge($input,['title'=>'ข่าวในอนาคต','slug'=>'future-news','status'=>'scheduled','published_at'=>date('Y-m-d\TH:i',time()+3600)]);
$futureId=save_content($future,$admin,null);check(visible_content('future-news','post')===null,'future scheduled content hidden');
query('UPDATE contents SET published_at=? WHERE id=?',[date('Y-m-d H:i:s',time()-60),$futureId]);check(visible_content('future-news','post')!==null,'scheduled content appears when due');
rejects(fn()=>save_content(array_merge($input,['slug'=>'bad-schedule','status'=>'scheduled']),$admin,null),'schedule needs future datetime');
rejects(fn()=>save_content(array_merge($input,['slug'=>'bad-link','external_url'=>'javascript:alert(1)']),$admin,null),'unsafe external URL rejected');
rejects(fn()=>normalize_datetime('2026-02-31T10:00'),'invalid calendar date rejected');
check(content_list('post',['q'=>"' OR 1=1 --"])['count']===0,'SQL injection search treated as text');
check(content_list('post',['q'=>'ข่าว'])['count']===2,'Thai search matches published items');
query("UPDATE contents SET status='trash' WHERE id=?",[$id]);check(visible_content('renamed-news','post')===null,'trash hidden from public');
check((int)query('SELECT COUNT(*) FROM revisions')->fetchColumn()>=4,'content revisions persisted');
check((int)query('SELECT COUNT(*) FROM audit_logs')->fetchColumn()>=4,'audit logs persisted');
check(e('<script>alert(1)</script>')==='&lt;script&gt;alert(1)&lt;/script&gt;','HTML output escaped');
check(str_contains(formatted_body("## หัวข้อ\n\n**ตัวหนา**\n\n- รายการ"),'<h2>หัวข้อ</h2>'),'formatted body supports headings');
check(!str_contains(formatted_body('<script>alert(1)</script>'),'\u003cscript>')&&!str_contains(formatted_body('<script>alert(1)</script>'),'<script>'),'formatted body escapes scripts');
check(str_contains(formatted_body('[ลิงก์](https://example.com?q=1&x=2)'), 'rel="noopener noreferrer"'),'formatted links are escaped and isolated');
check(!can_edit(one('SELECT * FROM contents WHERE id=?',[$futureId]),$author),'author cannot edit another user content');
check(safe_url('https://example.com')!==''&&safe_url('javascript:alert(1)')==='','safe URL allowlist');
$attachmentIds=[$cover];
for($n=1;$n<=1000;$n++) {
    query('INSERT INTO media (name,path,mime,size,alt,uploaded_by,created_at) VALUES (?,?,?,?,?,?,?)',["photo-$n.webp","test-$n.webp",'image/webp',100,'ภาพทดสอบ',$admin['id'],now()]);
