rejects(fn()=>save_content(array_merge($albumInput,['media_ids'=>$attachmentIds,'version'=>$albumRow['version']]),$admin,$albumRow),'1001 attachments rejected');
check((int)query('SELECT COUNT(*) FROM content_media WHERE content_id=?',[$albumId])->fetchColumn()===1000,'over-limit save preserves existing 1000 attachments');
